async function fetchDataset(config){const u=validateEndpoint(config.endpoint);const auth=config.auth||'bearer';const key=String(config.key||'');if(key.length>4096||/[\r\n]/.test(key))throw Error('인증 키 형식을 확인하세요.');const headers={'Accept':'application/json'};if(key){if(auth==='bearer')headers.Authorization='Bearer '+key;else if(auth==='x-api-key')headers['X-API-Key']=key;else if(auth==='auth-key')headers.AUTH_KEY=key;else throw Error('지원하지 않는 인증 방식입니다.');}const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),15000);try{const r=await fetch(u.toString(),{headers,redirect:'manual',signal:controller.signal});if(r.status>=300&&r.status<400)throw Error('API 주소가 다른 주소로 이동합니다. 최종 HTTPS 주소를 입력하세요.');if(!r.ok)throw Error('데이터 공급자가 HTTP '+r.status+'를 반환했습니다. 키·권한·호출 한도를 확인하세요.');const reader=r.body.getReader();let size=0;const parts=[];while(true){const {value,done}=await reader.read();if(done)break;size+=value.length;if(size>12*1024*1024){await reader.cancel();throw Error('응답은 12MB까지 지원합니다. 기간이나 종목 수를 줄여주세요.');}parts.push(value);}const all=new Uint8Array(size);let i=0;for(const p of parts){all.set(p,i);i+=p.length;}let raw;try{raw=JSON.parse(new TextDecoder().decode(all));}catch{throw Error('API 응답이 JSON 형식이 아닙니다.');}return engine.validate(raw);}catch(e){if(e.name==='AbortError')throw Error('API 응답 시간이 15초를 초과했습니다.');if(e.message?.startsWith('fetch'))throw Error('데이터 API에 연결하지 못했습니다. 주소와 공급자 상태를 확인하세요.');throw e;}finally{clearTimeout(timer);}}
