     +(got.length?'<ol class="dt-pay">'+got.slice().reverse().map(x=>'<li><span>'+x.payDate.replaceAll('-','.')+(x.payDate>asOf?' <em>지급 예정</em>':'')+'</span><span>'+x.fiscalYear+'년 '+(x.recordDate.slice(5)==='12-31'?'결산':'중간·분기')+' · 주당 '+num(x.dpsRaw,0)+'원</span><b>'+money(x.dps*q*(1-.154))+'</b></li>').join('')+'</ol>':'<p class="muted small">이 기간에는 받을 수 있는 배당이 없었어요.</p>')
     +'<div class="dt-grid"><div><span>주가 수익률</span><b class="'+tone(r.totalReturn)+'">'+pct(r.totalReturn)+'</b></div><div><span>배당 포함(세후)</span><b class="'+tone(r.profit+net)+'">'+pct((r.profit+net)/r.capital*100)+'</b></div><div><span>받은 횟수</span><b>'+got.length+'번</b></div></div>'
